<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { app, openSaved, openFile, refreshSaved, removeSaved, SHELF, type Box } from '../session'
import Bar from './Bar.vue'
onMounted(refreshSaved); const f = ref<HTMLInputElement>(), del = ref(''); const pick = (e: Event) => { const x = (e.target as HTMLInputElement).files?.[0]; if (x) openFile(x) }; const box = (s: any): Box | undefined => SHELF.find(b => b.id === s.mod); const base = import.meta.env.BASE_URL
const ago = (t: number) => new Date(t).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }); const line = (s: any) => { const b = box(s); return b ? [s.over ? 'Finished' : `Sitting ${(s.ch ?? 0) + 1} of ${b.chapters.length}: ${b.chapters[s.ch ?? 0]?.title ?? ''}`, s.place].filter(Boolean).join(', ') : s.camp && s.camp !== s.name ? s.name : s.mode === 'dm' ? 'A world of your own' : s.mode === 'ai' ? 'An invented tale' : 'Map' }
</script>
<template><main class="pg paper"><Bar title="Saved games" @back="app.screen = 'title'"><button class="btn" @click="f!.click()">Open a file</button><input ref="f" type="file" hidden @change="pick"></Bar>
  <div class="bd scroll"><p v-if="!app.saved.length" class="none">Nothing here yet. Every game you begin is kept in this browser.</p><div class="list"><article v-for="s in (app.saved as any[])" :key="s.id" :style="box(s) ? { '--d': box(s)!.inks[0], '--s': box(s)!.inks[1] } : {}"><button class="open" @click="openSaved(s.id)"><img v-if="box(s)" :src="`${base}ui/covers/${s.mod}.webp`" alt=""><img v-else-if="s.thumb" :src="s.thumb" alt=""><i v-else /><span class="t"><b>{{ s.camp || s.name }}</b><em>{{ line(s) }}</em><small>{{ s.heroes?.length ? s.heroes.join(', ') + (s.level ? `, level ${s.level}` : '') : 'No heroes yet' }}{{ s.mode === 'dm' ? '. You are the Dungeon Master' : '' }}</small><small>{{ ago(s.edited) }}</small></span></button><button class="rm" @click="del = s.id">Delete</button></article></div></div></main>
  <div v-if="del" class="veil" @click.self="del = ''"><section class="modal paper" style="width:420px"><div class="body"><h2>Delete this game?</h2><p style="margin-top:8px">It is removed from this browser. Heroes are kept.</p></div><footer><button class="btn quiet" @click="del = ''">Keep</button><button class="btn primary" @click="removeSaved(del); del = ''">Delete</button></footer></section></div></template>
<style scoped>.pg{position:fixed;inset:0;display:flex;flex-direction:column}.bd{flex:1;min-height:0}.none{padding:40px clamp(18px,3.2vw,48px)}.list{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,520px),1fr));gap:0 40px;padding:10px clamp(18px,3.2vw,48px) 60px;max-width:1500px}article{display:flex;align-items:center;border-bottom:2px solid var(--ink)}.open{display:flex;gap:20px;flex:1;min-width:0;align-items:stretch;padding:16px 0}.open:hover{background:var(--paper2)}img,.open>i{width:112px;height:132px;object-fit:cover;object-position:50% 60%;flex:none;background:var(--d,var(--paper3))}.t{min-width:0;display:grid;align-content:center;gap:3px}.t b{font:800 29px/1 var(--serif)}.t em{font-style:normal;font-size:17px;line-height:1.2}.t small{font-size:15.5px;color:var(--ink2)}.rm{padding:6px 10px;color:var(--ink2);text-decoration:underline;text-underline-offset:4px}.rm:hover{background:var(--bad);color:#fff}@media(max-width:640px){img,.open>i{width:76px;height:96px}.t b{font-size:23px}}</style>
